{
  "up": "Select molecule_chembl_id AS compound_chembl_id, canonical_smiles AS canonical_smiles From molecule_dictionary Join activities On molecule_dictionary.molregno = activities.molregno Join assays On activities.assay_id = assays.assay_id Join target_dictionary On assays.tid = target_dictionary.tid Join compound_structures On molecule_dictionary.molregno = compound_structures.molregno Where target_dictionary.chembl_id = 'CHEMBL1293235' And assays.assay_organism = 'Homo sapiens' Group By molecule_chembl_id canonical_smiles Sort By molecule_chembl_id canonical_smiles"
}
